import{z as B,x as A,o as t,c as d,q as r,j as n,D as E,d as s,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"OLS 与 Gauss–Markov","description":"","frontmatter":{"title":"OLS 与 Gauss–Markov","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/ols-gauss-markov.md","filePath":"econ/ols-gauss-markov.md","lastUpdated":1791063341000}'),u={name:"econ/ols-gauss-markov.md"};function m(p,a,h,c,C,D){const o=A("Mermaid");return t(),d("div",null,[a[2]||(a[2]=r('<h1 id="ols-与-gauss–markov" tabindex="-1">OLS 与 Gauss–Markov <a class="header-anchor" href="#ols-与-gauss–markov" aria-label="Permalink to &quot;OLS 与 Gauss–Markov&quot;">​</a></h1><div class="epigraph"><p>在线性、外生、球形误差下，OLS 是线性无偏类里方差最小的；这句话管的是精度，不是把 $\\beta$ 变成 ATE。</p><footer>—— 据 Gauss 最小二乘传统；Aitken 推广到 GLS；对照 Wooldridge, Econometric Analysis of Cross Section and Panel Data</footer></div><p><a href="/econ/potential-outcomes">上一课</a>把效应写成潜在结果的平均。本课缺口是最常用的估计装置：线性回归与 Gauss–Markov。后课先补<a href="/econ/hac-heteroskedasticity">异方差与 HAC</a>的推断，遗漏变量更后再拆外生；本课先钉：OLS 何时是 BLUE，以及 BLUE 不等于因果。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>潜在结果给出参数，没有给出算法。线性模型 \\(Y=X\\beta+u\\)、\\(\\mathbb{E}[u\\mid X]=0\\) 时，\\(\\beta\\) 是总体最佳线性预测的系数，也是条件期望若恰好线性时的斜率。缺口是分开三件事：预测、条件期望、因果。Gauss–Markov 只在第三层之外的精度层发言：线性无偏估计量中 OLS 方差最小，前提是外生与 \\(\\mathrm{Var}(u\\mid X)=\\sigma^2 I\\)。<span class="marginnote">BLUE 拆开念就不吓人了：Best——在线性无偏这个参赛组里方差最小；Linear——估计量是 \\(Y\\) 各分量的线性组合（形如 \\(c^\\top Y\\)）；Unbiased——平均下来正中 \\(\\beta\\)。注意「最好」只在跟同组比：非线性估计量、或故意引入一点偏差换大幅降方差的方法，都不在这场比赛里，Gauss–Markov 对它们不置一词。</span></p><p>随机化下，\\(D\\) 的系数可以等于 ATE（或不加控制时的简单差）。加上控制、非线性真实 CEF、异质 \\(\\tau_i\\)，OLS 变成加权平均，权重由 Angrist 的「回归加权」给出——那是后课异质，本课先承认：同质性加线性时，\\(\\beta\\) 才直接等于 ATE。</p><p><span class="marginnote">BLUE：Best Linear Unbiased Estimator。线性指估计量是 \\(Y\\) 的线性函数。无偏需要外生。球形误差失败时 OLS 仍可一致，只是不再方差最小，要用 GLS 或稳健标准误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>正规方程 \\(X&#39;X\\hat\\beta=X&#39;Y\\)。投影解释：\\(\\hat Y\\) 是 \\(Y\\) 在 \\(X\\) 列空间上的正交投影，残差与 \\(X\\) 正交。<span class="marginnote">「正交投影」可以想象成阳光下的影子：\\(Y\\) 是空中一点，\\(X\\) 的列空间是地面，\\(\\hat Y\\) 就是 \\(Y\\) 投在地面上的影子——地面上离 \\(Y\\) 最近的那个点。残差 \\(Y-\\hat Y\\) 是连接 \\(Y\\) 与影子的那根竖线，天然与地面垂直（正交）；OLS 选系数，就是选一个影子位置让这根竖线最短。</span>Frisch–Waugh–Lovell：多元回归中 \\(x_1\\) 的系数，等于把 \\(Y\\) 与 \\(x_1\\) 都对其余回归元残差化后再做一元回归。后课遗漏变量、固定效应、都从这条残差化来读。</p>',9)),(t(),n(l,null,{default:E(()=>[i(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIN%5B%22%E7%BA%BF%E6%80%A7%20%2B%20%E5%A4%96%E7%94%9F%22%5D%20--%3E%20OLS%5B%22OLS%20%E6%97%A0%E5%81%8F%20%2F%20%E4%B8%80%E8%87%B4%22%5D%0A%20%20SPH%5B%22%E7%90%83%E5%BD%A2%E8%AF%AF%E5%B7%AE%22%5D%20--%3E%20GM%5B%22Gauss%E2%80%93Markov%3A%20BLUE%22%5D%0A%20%20OLS%20--%3E%20GM%0A%20%20HET%5B%22%E5%BC%82%E6%96%B9%E5%B7%AE%20%2F%20%E7%9B%B8%E5%85%B3%22%5D%20--%3E%20ROB%5B%22%E4%BB%8D%E4%B8%80%E8%87%B4%2C%20%E4%B8%8D%E5%86%8D%20BLUE%22%5D%0A%20%20CAU%5B%22%E5%9B%A0%E6%9E%9C%22%5D%20--%3E%20PO%5B%22%E4%BB%8D%E8%A6%81%E6%BD%9C%E5%9C%A8%E7%BB%93%E6%9E%9C%E5%81%87%E8%AE%BE%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"大样本：外生加有限矩，OLS 一致、渐近正态。正态误差给出精确 \\(t\\)；经济学默认用渐近，把精确正态当特例。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[s("机制是正交投影。\\(\\mathbb{E}[u\\mid X]=0\\) 使 \\(X\\) 与误差不相关，斜率对准条件期望（线性时）。因果要的是 \\(X\\) 与"),e("strong",null,"潜在结果的噪声"),s("不相关，比「与观测残差不相关」更强。预测可以不管因果：房价对面积的回归仍有用。政策要把面积当成可干预的 \\(D\\)，必须回到上一课的赋值。")],-1)),a[6]||(a[6]=e("p",null,[s("Gauss–Markov 不管一致性之外的稳健：一条杠杆点可以毁掉有限样本。"),e("span",{class:"marginnote"},"杠杆点的威力可以估一估：30 个点挤在 \\(x\\in[0,10]\\)，另有一个远点 \\(x=1000\\)。算 \\(X'X\\) 时，远点一家贡献约 \\(1000^2=10^6\\)，其余 30 家合计不到 \\(10^3\\)——差三个数量级。正规方程几乎只听它一个的，斜率挪一挪、甚至翻个方向，全凭它高兴。这也是回归前先画散点图、查影响点的原因。"),s("它也不给聚类依赖下的正确精度——那是"),e("a",{href:"/econ/inference-robust-cluster"},"稳健、聚类"),s("的缺口。量化栏的金融回归有另一套 HAC 与因子，本课不搬过去，以免吞并。")],-1)),(t(),n(l,null,{default:E(()=>[i(o,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20Y%5B%22Y%22%5D%20--%3E%7C%E5%AF%B9%E5%85%B6%E4%BD%99%E5%9B%9E%E5%BD%92%E5%85%83%E5%9B%9E%E5%BD%92%E5%8F%96%E6%AE%8B%E5%B7%AE%7C%20RY%5B%22%E6%AE%8B%E5%B7%AE%E5%8C%96%E7%9A%84%20%E1%BB%B8%22%5D%0A%20%20X1%5B%22x1%22%5D%20--%3E%7C%E7%94%A8%E5%90%8C%E6%A0%B7%E7%9A%84%E5%85%B6%E4%BD%99%E5%9B%9E%E5%BD%92%E5%85%83%E6%AE%8B%E5%B7%AE%E5%8C%96%7C%20RX%5B%22%E6%AE%8B%E5%B7%AE%E5%8C%96%E7%9A%84%20x%CC%831%22%5D%0A%20%20RY%20--%3E%20SIM%5B%22%E1%BB%B8%20%E5%AF%B9%20x%CC%831%20%E5%81%9A%E4%B8%80%E5%85%83%E5%9B%9E%E5%BD%92%22%5D%0A%20%20RX%20--%3E%20SIM%0A%20%20SIM%20--%3E%20B%5B%22%E6%96%9C%E7%8E%87%20%3D%20%E5%A4%9A%E5%85%83%E5%9B%9E%E5%BD%92%E4%B8%AD%20x1%20%E7%9A%84%E7%B3%BB%E6%95%B0%EF%BC%88FWL%EF%BC%89%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">下一课 HAC 先修标准误。遗漏变量仍在更后：漏掉的 \\(w\\) 进入残差，若 \\(\\mathrm{Cov}(X,w)\\neq 0\\)，外生失败，BLUE 无从谈起。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 \\(R^2\\) 当因果证据。不引入工具。非线性 CEF 上 OLS 仍是最佳线性近似（在 \\(X\\) 的测度下），Angrist–Pischke 强调这一点：线性化是特征，不是 bug；但近似权重必须声明。面板、时间序列的依赖结构会破坏球形，本课只标出来。</p><p>后课默认：写下 OLS 时，先问外生针对的是 CEF 还是潜在结果；Gauss–Markov 只在球形下给精度排名。下一课先写 White / Newey–West；外生失败的两种形状交给更后的遗漏变量课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OLS 是正交投影；外生时对准线性 CEF。</li><li>Gauss–Markov：线性无偏类中方差最小，不管因果。</li><li>FWL 把多元系数收成残差化一元回归，后课反复用。</li><li>异质与非线性时，\\(\\beta\\) 是加权平均，不是自动 ATE。</li><li>出处：Gauss–Markov 传统；Wooldridge 截面与面板；Angrist and Pischke, <em>Mostly Harmless Econometrics</em>。</li></ul>',6))])}const k=B(u,[["render",m]]);export{S as __pageData,k as default};
